const BY_KEY = new Map(JOURNALS.map((j) => [j.week + '/' + j.slug, j]));

function findJournal(weekNumber, slug) {
  return BY_KEY.get(Number(weekNumber) + '/' + String(slug)) || null;
}

function allPrompts(journal) {
  const out = [];
  for (const section of (journal && journal.sections) || []) {
    for (const prompt of section.prompts || []) out.push(prompt);
  }
  return out;
}

function journalsForWeek(weekNumber, options = {}) {
  return JOURNALS.filter((j) => j.week === Number(weekNumber) && (options.includeHidden || j.listed !== false));
}

module.exports = { JOURNALS, findJournal, allPrompts, journalsForWeek, DOCS_DIR };
